    private ClassicLecternItemModel() {}
    public static void render(PoseStack poses, MultiBufferSource buffers, int light, int overlay) {
        poses.pushPose(); poses.translate(.5, 0, .5);
        var vertices = buffers.getBuffer(RenderType.entitySolid(TEXTURE));
        for (var face : QUADS) for (var point : face)
            vertices.vertex(poses.last().pose(), point[0], point[1], point[2]).color(1F,1F,1F,1F)
                    .uv(point[3], 1 - point[4]).overlayCoords(overlay).uv2(light)
                    .normal(poses.last().normal(), point[5], point[6], point[7]).endVertex();
        poses.popPose();
    }
